        $addItem($roots['Звук и музыка'], 'Собрать базовую звуковую библиотеку', 'Звук — 70% эмоционального воздействия; музыка запрещена до титров.', [['Аудио', 'Производственные звуки', 18], ['Документ', 'Звуковая библия', 1]]);
        $addItem($roots['Юридические документы'], 'Собрать согласия и лицензии', 'Права на лица, голоса, животных, локации, музыку и внешние материалы.', [['Документ', 'Юридические согласия', 5]]);
        foreach (['A1-S01 Утренний ритуал', 'A2-S01 Натянутый поводок', 'A2-S02 Старуха и правда', 'A3-S01 Последний фонарь'] as $title) {
            $addItem($roots['Тестовые эпизоды'], 'Тестовый эпизод: '.$title, 'Проверить постоянство персонажей, камеры, погоды, цвета и звука.', [['Видео', 'Утверждённый тестовый ролик', 1], ['Фото', 'Ключевые кадры', 4], ['Документ', 'Разбор теста', 1]]);
        }
        $addItem($roots['Готовность к производству'], 'Провести итоговую проверку ядра', 'Карточка, сценарий, персонажи, места, реквизит, звук и тесты готовы.', [['Документ', 'Протокол готовности', 1]]);

        $docs = [
            ['Утверждённая карточка проекта', 'Карточка проекта', 'database/seed-data/project-card.txt', 'DOC/The Silent Companion.docx', 'The Silent Companion.docx'],
            ['Режиссёрская экспликация', 'Режиссёрская экспликация', 'database/seed-data/director-statement.txt', 'DOC/режиссерская экспликация.docx', 'режиссерская экспликация.docx'],
        ];
        foreach ($docs as [$title,$type,$contentPath,$sourcePath,$sourceName]) {
            $content = file_get_contents(base_path($contentPath));
            $document = Document::create(['project_id' => $project->id, 'updated_by' => $user->id, 'title' => $title, 'type' => $type, 'content' => $content, 'source_path' => $sourcePath, 'source_name' => $sourceName, 'version' => 1]);
            $document->versions()->create(['user_id' => $user->id, 'version' => 1, 'content' => $content, 'change_note' => 'Первоначальный импорт из DOC']);
        }

        PublicSiteSetting::create(['project_id' => $project->id, 'public_summary' => 'Тихая психологическая драма о человеке и старом лабрадоре, который возвращает хозяина к людям и передаёт ему новый ритуал жизни.']);
